import { defineStore } from 'pinia'

export const useProgressTracker = defineStore('progress', {
  state: () => ({ done: [] as string[] }),
  getters: {
    percentOf: (state) => (total: number) =>
      total === 0 ? 0 : Math.round((state.done.length * 100) / total)
  },
  actions: {
    mark(id: string) {
      if (!this.done.includes(id)) this.done.push(id)
    }
  }
})
